			let tmpName = (document.querySelector('.facto-analyze-field-name[data-idx="' + i + '"]') || {}).value || tmpFields[i].Name;
			let tmpType = (document.querySelector('.facto-analyze-field-type[data-idx="' + i + '"]') || {}).value || tmpFields[i].DataType;

