			+ '<div style="overflow-x:auto; white-space:nowrap; display:flex; align-items:flex-end; height:' + HISTOGRAM_HEIGHT + 'px; border-bottom:1px solid rgba(0,0,0,0.1);">'
			+ tmpBarsHtml
			+ '</div>'
			+ '</div>';
